import{_ as n,o as a,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"制造与工厂提示词模板","description":"制造与工厂的 5 条提示词模板：作业指导书、质检与不良分析、设备点检、安全培训、排产交期。","frontmatter":{"title":"制造与工厂提示词模板","description":"制造与工厂的 5 条提示词模板：作业指导书、质检与不良分析、设备点检、安全培训、排产交期。"},"headers":[],"relativePath":"community/prompts/制造与工厂.md","filePath":"community/prompts/制造与工厂.md"}'),e={name:"community/prompts/制造与工厂.md"};function l(i,s,o,c,r,u){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🏭-制造与工厂-·-5-条提示词模板" tabindex="-1">🏭 制造与工厂 · 5 条提示词模板 <a class="header-anchor" href="#🏭-制造与工厂-·-5-条提示词模板" aria-label="Permalink to &quot;🏭 制造与工厂 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>车间的活儿最讲究&quot;写下来&quot;： <strong>没写下来的标准，等于没有标准</strong>；<strong>没记录的异常，下次还会再来一次</strong>。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们是【什么工厂 / 什么产品 / 车间还是品控岗位】，现在要处理【什么事】。</span></span>
<span class="line"><span>帮我产出【作业指导书 / 记录表 / 培训材料】，形式【…】。</span></span>
<span class="line"><span>按我们实际的设备、工序、标准来；我不给的参数一律留空，不许估。</span></span></code></pre></div><hr><h2 id="_1-·-作业指导书-sop-让新人也照着能做对" tabindex="-1">1 · 作业指导书 / SOP（让新人也照着能做对） <a class="header-anchor" href="#_1-·-作业指导书-sop-让新人也照着能做对" aria-label="Permalink to &quot;1 · 作业指导书 / SOP（让新人也照着能做对）&quot;">​</a></h2><p><strong>什么时候用</strong>：老师傅会做，但说不清；新人来了靠&quot;跟着看&quot;，学得慢还容易出错。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工序名称：【…】</span></span>
<span class="line"><span>要做的产品与规格：【…】</span></span>
<span class="line"><span>我现有的关键信息：</span></span>
<span class="line"><span>- 设备与工装：【…】</span></span>
<span class="line"><span>- 材料与规格：【…】</span></span>
<span class="line"><span>- 关键参数（温度/压力/时间/速度等）：【…，能给区间就给区间】</span></span>
<span class="line"><span>- 最容易出错的三个地方：【…】</span></span>
<span class="line"><span>- 判断合格的标准：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写成一份作业指导书：</span></span>
<span class="line"><span>① 目的与适用范围（一句话）</span></span>
<span class="line"><span>② 准备工作（材料、工具、劳保用品、开机检查）</span></span>
<span class="line"><span>③ 操作步骤（编号，每步一句动作 + 一句&quot;做到什么程度&quot;，含关键参数）</span></span>
<span class="line"><span>④ 常见异常与处理（表格：现象 / 可能原因 / 怎么处理 / 什么时候必须停机报修）</span></span>
<span class="line"><span>⑤ 合格判定标准 + 记录要求（填哪张表、多久填一次）</span></span>
<span class="line"><span>⑥ 安全注意（每条对应一个真实风险点）</span></span>
<span class="line"><span>规矩：参数只能用我给的；我不给的地方写&quot;待填写&quot;；不要写&quot;按规范操作&quot;这种没有内容的表述。</span></span></code></pre></div><p><strong>它给你</strong>：一份能贴在工位旁的指导书。</p><hr><h2 id="_2-·-质检记录与不良分析-8d-的思路" tabindex="-1">2 · 质检记录与不良分析（8D 的思路） <a class="header-anchor" href="#_2-·-质检记录与不良分析-8d-的思路" aria-label="Permalink to &quot;2 · 质检记录与不良分析（8D 的思路）&quot;">​</a></h2><p><strong>什么时候用</strong>：出现批量不良，大家忙着救火，没人写下来&quot;到底为什么&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品 / 批次：【…】，发现时间：【…】，发现环节：【来料/过程/出货/客户投诉】</span></span>
<span class="line"><span>不良现象：【具体描述，最好带数量、比例、照片说明】</span></span>
<span class="line"><span>我已经查过的：</span></span>
<span class="line"><span>- 同批次其他产品：【…】</span></span>
<span class="line"><span>- 设备状态：【…】</span></span>
<span class="line"><span>- 换过料/换过人/换过模：【…】</span></span>
<span class="line"><span>- 上次出现类似问题：【有/没有，怎么解决的】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我梳理：</span></span>
<span class="line"><span>① 问题描述（一句能让没到现场的人听懂的话，含数量、比例、影响范围）</span></span>
<span class="line"><span>② 临时对策（先止血：挑出、隔离、返工、通知客户，按时间写）</span></span>
<span class="line"><span>③ 可能原因清单（人、机、料、法、环、测六类各列可能的点，按可能性排序）</span></span>
<span class="line"><span>④ 每个原因的验证方法（怎么用最少成本确认是不是它）</span></span>
<span class="line"><span>⑤ 纠正措施与预防措施（分别写&quot;怎么改&quot;和&quot;怎么防止再来&quot;）</span></span>
<span class="line"><span>⑥ 需要留档的记录清单</span></span>
<span class="line"><span>规矩：不做没有依据的结论；原因全是&quot;待验证&quot;，不许直接断定某一项；我不给的数字不填。</span></span></code></pre></div><p><strong>它给你</strong>：一份完整的异常分析框架 + 验证方法。</p><hr><h2 id="_3-·-设备点检表-日常-周-月" tabindex="-1">3 · 设备点检表（日常 / 周 / 月） <a class="header-anchor" href="#_3-·-设备点检表-日常-周-月" aria-label="Permalink to &quot;3 · 设备点检表（日常 / 周 / 月）&quot;">​</a></h2><p><strong>什么时候用</strong>：点检表用了好几年，有些项早就不适用了，工人也懒得填。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备名称与型号：【…】，数量：【…】</span></span>
<span class="line"><span>使用频率与班次：【…】</span></span>
<span class="line"><span>以前出过的故障（最近一年）：【…】</span></span>
<span class="line"><span>厂家要求的保养项：【有就粘贴，没有就写&quot;无&quot;】</span></span>
<span class="line"><span>现在用的点检表存在的问题：【例如项太多填不完 / 有些项没有标准】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我重做一张点检表：</span></span>
<span class="line"><span>① 按&quot;班前 / 班中 / 班后 / 周 / 月&quot;分层，班次项控制在 8 条以内（填得完才会填）</span></span>
<span class="line"><span>② 每条写清&quot;看什么、正常是什么样、不正常怎么办、谁负责&quot;</span></span>
<span class="line"><span>③ 加上&quot;必须立即停机上报&quot;的判定项，并用视觉方式标出（例如用醒目标记）</span></span>
<span class="line"><span>④ 记录方式建议（打勾/数值/拍照），以及保留期限</span></span>
<span class="line"><span>⑤ 一份 5 分钟的培训讲法（怎么教新员工用这张表）</span></span>
<span class="line"><span>规矩：保养周期和参数按我给的信息来；不确定的写&quot;以设备手册为准&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一张填得完、看得懂的点检表。</p><hr><h2 id="_4-·-安全培训材料-讲得进去才有用" tabindex="-1">4 · 安全培训材料（讲得进去才有用） <a class="header-anchor" href="#_4-·-安全培训材料-讲得进去才有用" aria-label="Permalink to &quot;4 · 安全培训材料（讲得进去才有用）&quot;">​</a></h2><p><strong>什么时候用</strong>：安全培训年年讲，工人在下面玩手机，出了事还是那几个原因。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>培训对象：【岗位 / 新员工还是全员 / 学历和接受度】</span></span>
<span class="line"><span>我要讲的内容（我来确认真实的风险和规程）：【…】</span></span>
<span class="line"><span>车间里真实发生过 / 差点发生的事：【…（可脱敏）】</span></span>
<span class="line"><span>时长：【…】，形式：【讲解 / 现场演示 / 演练】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 开场 1 分钟：用一个&quot;就在我们车间发生过的&quot;场景切入（用我给的素材）</span></span>
<span class="line"><span>② 主体：把要讲的内容拆成 5 个以内的要点，每点配一个&quot;做错会怎样&quot;的具体后果</span></span>
<span class="line"><span>③ 3 个互动提问（不是&quot;听懂了吗&quot;，而是&quot;如果遇到 X 你第一步做什么&quot;）</span></span>
<span class="line"><span>④ 结尾：3 条必须记住的硬规矩 + 一句好记的口诀</span></span>
<span class="line"><span>⑤ 另附：一份 10 题的现场小测（含答案和解释）</span></span>
<span class="line"><span>⑥ 一份培训签到与效果确认表模板</span></span>
<span class="line"><span>规矩：不编事故案例；不引用我不提供的法规条款；不写恐吓式内容，只讲真实后果。</span></span></code></pre></div><p><strong>它给你</strong>：讲得进去的培训材料 + 小测 + 签到表。</p><hr><h2 id="_5-·-排产与交期沟通-订单多、产能紧的时候" tabindex="-1">5 · 排产与交期沟通（订单多、产能紧的时候） <a class="header-anchor" href="#_5-·-排产与交期沟通-订单多、产能紧的时候" aria-label="Permalink to &quot;5 · 排产与交期沟通（订单多、产能紧的时候）&quot;">​</a></h2><p><strong>什么时候用</strong>：一堆订单挤在一起，车间说做不完，销售说客户催得急，你在中间。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单情况（有几单写几单）：【订单号 / 产品 / 数量 / 客户要求交期 / 紧急程度 / 是否可分批】</span></span>
<span class="line"><span>产能情况：【每天/每周能做多少 / 现在手上排了多少 / 有没有设备检修或人手不足】</span></span>
<span class="line"><span>物料情况：【哪些料的到货时间会影响排产】</span></span>
<span class="line"><span>限制条件：【换模时间 / 某个产品的特殊要求 / 必须优先的客户】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 排一个可执行的周计划（哪天做什么、做多少、几点换模）</span></span>
<span class="line"><span>② 标出&quot;无论如何都赶不上&quot;的订单，以及赶不上的原因（用数据说）</span></span>
<span class="line"><span>③ 给每个赶不上的订单两个方案（分批交 / 延后），并写清各自的代价</span></span>
<span class="line"><span>④ 写一条给销售的内部说明（不推责、给事实、给选择）</span></span>
<span class="line"><span>⑤ 写一条给客户的交期说明要点（由销售去发，语气自己掌握）</span></span>
<span class="line"><span>规矩：产能数字只用我给的；不许&quot;挤一挤应该能行&quot;这种拍脑袋；算不出来的地方明说需要什么数据。</span></span></code></pre></div><p><strong>它给你</strong>：一张能落地的周计划 + 赶不上的应对方案。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>安全和工艺参数不能由 AI 定</strong>：温度、压力、时间、防护要求，必须以设备手册和真实工艺文件为准。<strong>AI 写的只能是&quot;把我说的整理清楚&quot;，不能是&quot;帮我想一个参数&quot;。</strong></li><li><strong>不编事故、不编数据</strong>：培训材料和异常报告里的每一个事例，都必须是真实发生过的。</li><li><strong>客户与工艺信息分级</strong>：客户名、图纸、配方、成本，给 AI 处理前一律脱敏或改用代号。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 全部看完了 → <strong><a href="/MoMAWork-/community/prompts/">回到模板库首页</a></strong></p>`,34)])])}const g=n(e,[["render",l]]);export{d as __pageData,g as default};
